const SIDE = 6

function fixture(): ArrayBuffer {
  const bytes = Uint8Array.from(atob(FIXTURE), (c) => c.charCodeAt(0))
  return bytes.buffer
}

function firstMesh(root: THREE.Object3D): THREE.Mesh {
  let found: THREE.Mesh | null = null
  root.traverse((o) => {
    if (!found && (o as THREE.Mesh).isMesh) found = o as THREE.Mesh
  })
  if (!found) throw new Error('no mesh')
  return found
}

describe('meshoptGeometry3d', () => {
  it('decodes compressed geometry into the uncompressed types, within the server bounds', async () => {
    const gltf = await withMeshopt(new GLTFLoader()).parseAsync(fixture(), '')
    const g = firstMesh(gltf.scene).geometry
    const pos = g.getAttribute('position') as THREE.BufferAttribute
    const uv = g.getAttribute('uv') as THREE.BufferAttribute
    expect(pos.array).toBeInstanceOf(Float32Array)
    expect(uv.array).toBeInstanceOf(Float32Array)
    expect(pos.normalized).toBe(false)
    expect(g.index?.array).toBeInstanceOf(Uint32Array)
    expect(g.index?.count).toBe((SIDE - 1) * (SIDE - 1) * 6)
    for (let y = 0; y < SIDE; y++) {
      for (let x = 0; x < SIDE; x++) {
        const i = y * SIDE + x
        // Float32 inputs as the Go generator makes them, then the 2^-11 bound (half a 2^-10 step).
        const want = [Math.fround(Math.fround(x * 0.37) + 100.0001), Math.fround(Math.sin(x * y) * 3), Math.fround(Math.fround(y * 0.41) - 250.0003)]
        expect(Math.abs(pos.getX(i) - want[0])).toBeLessThanOrEqual(2 ** -11)
        expect(Math.abs(pos.getY(i) - want[1])).toBeLessThanOrEqual(2 ** -11)
        expect(Math.abs(pos.getZ(i) - want[2])).toBeLessThanOrEqual(2 ** -11)
        expect(Math.abs(uv.getX(i) - Math.fround(x / 7.3))).toBeLessThanOrEqual(2 ** -20)
        expect(Math.abs(uv.getY(i) - Math.fround(y / 3.1))).toBeLessThanOrEqual(2 ** -20)
      }
    }
    // The accessor bounds were rewritten from the decoded positions.
    g.computeBoundingBox()
    expect(g.boundingBox!.min.x).toBeCloseTo(100, 3)
  })

  it('is registered by withKtx2, with or without a KTX2 loader', async () => {
    const gltf = await withKtx2(new GLTFLoader(), null).parseAsync(fixture(), '')
    expect(firstMesh(gltf.scene).geometry.getAttribute('position').count).toBe(SIDE * SIDE)
  })

  it('fails loudly on a loader without the decoder (the extension is required)', async () => {
    await expect(new GLTFLoader().parseAsync(fixture(), '')).rejects.toThrow(/setMeshoptDecoder/)
  })
})